from pathlib import Path
import base64, gzip, subprocess, hashlib

PATCH_B64 = r""""""

base = Path("Dr_Fortress_AI_V12_FIX04.per")
out = Path("Dr_Fortress_AI_V12_FIX05.per")
out.write_bytes(base.read_bytes())
patch = gzip.decompress(base64.b64decode(PATCH_B64))
Path("support/V12_FIX05.generated.patch").write_bytes(patch)
subprocess.run(["git", "apply", "support/V12_FIX05.generated.patch"], check=True)
Path("Dr_Fortress_AI_V12_FIX05.ai").write_bytes(Path("Dr_Fortress_AI_V12_FIX04.ai").read_bytes())
sha = hashlib.sha256(out.read_bytes()).hexdigest()
expected = "102148b13418b031a65e70ed402f17939b74658255d82d1dfb36d6bb0a1eafa5"
if sha != expected:
    raise SystemExit(f"FIX05 SHA mismatch: {sha} != {expected}")
print("FIX05 built and SHA verified:", sha)
